cardCss:
.dino-card {
  --dino: #4D96FF;
  position: relative;
  border-radius: 22px;
  border: 4px solid #fff;
  background: var(--dino);
  color: #fff;
  padding: 12px 14px 14px;
  margin-bottom: 16px;
  box-shadow: 0 10px 22px rgba(60,50,120,.16);
  font-family: 'Fredoka','Baloo 2','Comic Sans MS','Chalkboard SE',system-ui,sans-serif;
  overflow: hidden;
}
/* actions float top-right */
.dino-acts { position:absolute; top:10px; right:10px; display:flex; gap:8px; z-index:4; }
.dc-act {
  width:40px;height:40px;border-radius:9999px;display:inline-flex;align-items:center;justify-content:center;
  background: rgba(255,255,255,.9); color:#33415a; border:none; cursor:pointer; font-size:17px;
  transition: all .18s ease; box-shadow: 0 3px 8px rgba(0,0,0,.12);
}
.dc-act:hover { transform: translateY(-2px) scale(1.06); color:#111; }
.dc-act:active { transform: scale(.9); }
.dc-act.is-active { background:#fff; color:#ff5b8a; }
.dc-act.act-fav.is-active { color:#ffb800; }
.dc-act.act-mark.is-active { color:#7a3fb0; }
/* graphic-dominant: huge dino on the left, compact text column on the right */
.dino-stage { display:flex; align-items:center; gap:8px; margin-top:4px; }
.dino-graphic {
  flex:1 1 auto; min-width:0; display:flex; align-items:center; justify-content:center;
  cursor:pointer; user-select:none;
}
.dino-emoji { font-size:182px; line-height:1; filter: drop-shadow(2px 6px 5px rgba(0,0,0,.22)); animation: dinoBob 2.6s ease-in-out infinite; }
@keyframes dinoBob { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-7px)} }
.dino-side { flex:0 0 31%; min-width:92px; text-align:left; }
.dino-letter {
  font-family:'Baloo 2','Fredoka',sans-serif; font-weight:800; font-size:82px; line-height:.86;
  text-shadow: 2px 3px 0 rgba(0,0,0,.22); margin-bottom:2px;
}
.dino-name { font-weight:700; font-size:15px; letter-spacing:.2px; text-shadow:1px 1px 0 rgba(0,0,0,.12); }
.dino-zh { font-size:12px; opacity:.95; }
.dino-ph { display:inline-block; margin-top:5px; background:rgba(255,255,255,.92); color:#333; font-weight:700; font-size:12px; padding:2px 10px; border-radius:999px; }
.dino-hint { margin-top:6px; font-size:11px; font-weight:600; opacity:.9; }
.dino-star { position:absolute; right:12px; bottom:10px; font-size:22px; color:rgba(255,255,255,.55); transition:.2s; opacity:0; pointer-events:none; }
.dino-card.collected .dino-star { opacity:1; color:#fff; text-shadow:0 0 8px rgba(255,255,255,.85); }
.dino-fun {
  margin-top:8px; background:rgba(255,255,255,.96); color:#5b2a86; font-weight:600;
  border-radius:14px; padding:0 12px; font-size:14px; max-height:0; overflow:hidden; opacity:0; transition: all .3s ease;
}
.dino-fun.show { padding:10px 12px; max-height:220px; opacity:1; }
.dino-vis { margin-top:8px; font-size:12px; opacity:.88; line-height:1.5; background:rgba(0,0,0,.13); border-radius:10px; padding:6px 10px; }
.dino-card.roar { animation: dinoRoar .55s ease; }
@keyframes dinoRoar { 0%{transform:scale(1)} 30%{transform:scale(1.05) rotate(2deg)} 60%{transform:scale(.97) rotate(-2deg)} 100%{transform:scale(1)} }
body.dark-mode .dino-card { color:#fff; }

cardJs:
(function () {
  'use strict';
  function esc(s) {
    if (s == null) return '';
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }
  var PAL = ['#FF6B6B','#FFD93D','#6BCB77','#4D96FF','#FF9F45','#B983FF','#FF6FB5','#3DCCC7'];
  window.cardTemplate = {
    name: 'Dino Alphabet',
    fields: [
      { key: 'letter', label: '字母', hideable: false },
      { key: 'dinoEn', label: '恐龙(英)' },
      { key: 'dinoZh', label: '恐龙(中)' },
      { key: 'emoji', label: '恐龙形象', hideable: false },
      { key: 'color', label: '主题色', hideable: false },
      { key: 'phonics', label: '发音' },
      { key: 'sampleWord', label: '示例词' },
      { key: 'visual', label: '视觉构思' },
      { key: 'fun', label: '趣味点子' }
    ],
    render: function (cardHtml, cardData, api) {
      var data = api.getCardData ? api.getCardData() : cardData;
      var d = data.data || {};
      var id = data.id;
      var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
      function isHidden(k) { return hidden.has && hidden.has(k); }
      function h(k, html) { return isHidden(k) ? '' : html; }
      var color = d.color || PAL[((id || 0) % PAL.length + PAL.length) % PAL.length];

      var html = '';
      html += '<div class="dc-card dino-card" data-card-id="' + id + '" style="--dino:' + esc(color) + ';background:' + esc(color) + '">';
      // actions (top-right)
      html += '  <div class="dino-acts">';
      html += '    <button class="dc-act act-play" data-action="play" title="听一听"><i class="fa-solid fa-volume-high"></i></button>';
      html += '    <button class="dc-act act-mark" data-action="mark" title="标记"><i class="fa-solid fa-bookmark"></i></button>';
      html += '    <button class="dc-act act-fav" data-action="favorite" title="收藏"><i class="fa-solid fa-star"></i></button>';
      html += '  </div>';
      // graphic-dominant body: huge dino left, compact text right
      html += '  <div class="dino-stage">';
      html += '    <div class="dino-graphic" data-action="collect"><div class="dino-emoji">' + esc(d.emoji || '🦕') + '</div></div>';
      html += '    <div class="dino-side">';
      html += '      <div class="dino-letter">' + esc(d.letter || '') + '</div>';
      html += h('dinoEn', '      <div class="dino-name">' + esc(d.dinoEn || '') + '</div>');
      html += h('dinoZh', '      <div class="dino-zh">' + esc(d.dinoZh || '') + '</div>');
      html += h('phonics', '      <div class="dino-ph">' + esc(d.phonics || '') + '</div>');
      html += '      <div class="dino-hint">🦕 点我嗷呜！</div>';
      html += '    </div>';
      html += '  </div>';
      // collected star
      html += '  <div class="dino-star"><i class="fa-solid fa-star"></i></div>';
      // fun bubble (revealed on tap)
      html += h('fun', '  <div class="dino-fun">' + esc(d.fun || '') + '</div>');
      // visual design note (hideable, muted)
      html += h('visual', '  <div class="dino-vis">💡 ' + esc(d.visual || '') + '</div>');
      html += '</div>';
      return html;
    },
    init: function (el, cardData, api) {
      var data = api.getCardData ? api.getCardData() : cardData;
      var d = data.data || {};
      if (data.is_unknown) { var m0 = el.querySelector('.act-mark'); if (m0) m0.classList.add('is-active'); }
      if (data.is_favorite) { var f0 = el.querySelector('.act-fav'); if (f0) f0.classList.add('is-active'); }

      var playBtn = el.querySelector('.act-play');
      if (playBtn) playBtn.addEventListener('click', function (e) {
        e.stopPropagation();
        // read ONLY the ALPHABET LETTER being learned — never the dinosaur name
        var txt = d.letter || '';
        api.playAudio(txt);
        api.track('audio_play');
      });
      var markBtn = el.querySelector('.act-mark');
      if (markBtn) markBtn.addEventListener('click', function (e) {
        e.stopPropagation();
        api.toggleMark().then(function () { markBtn.classList.toggle('is-active'); });
        api.track('word_mark');
      });
      var favBtn = el.querySelector('.act-fav');
      if (favBtn) favBtn.addEventListener('click', function (e) {
        e.stopPropagation();
        api.toggleFavorite().then(function () { favBtn.classList.toggle('is-active'); });
        api.track('favorite_toggle');
      });

      function roar() {
        el.classList.remove('roar'); void el.offsetWidth; el.classList.add('roar');
        el.classList.add('collected');
        var fb = el.querySelector('.dino-fun'); if (fb) fb.classList.add('show');
        try {
          var AC = window.AudioContext || window.webkitAudioContext;
          if (AC) {
            var ac = new AC();
            var o = ac.createOscillator(), g = ac.createGain();
            o.type = 'sawtooth';
            o.frequency.setValueAtTime(200, ac.currentTime);
            o.frequency.exponentialRampToValueAtTime(70, ac.currentTime + 0.4);
            g.gain.setValueAtTime(0.10, ac.currentTime);
            g.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 0.45);
            o.connect(g); g.connect(ac.destination); o.start(); o.stop(ac.currentTime + 0.45);
          }
        } catch (e) {}
        api.track('collect');
      }
      var graphic = el.querySelector('.dino-graphic');
      if (graphic) graphic.addEventListener('click', function (e) { e.stopPropagation(); roar(); });
    }
  };
})();
